/*
 * Modified by Actuna Sp. z o.o.:
 *   #63: new file - a harness for the tests of the update of a project (PUT /projects/:id): a real project in a
 *   directory of its own (a git repository with README.md, package.json and the flow files), the real storage of the
 *   projects and the real project API, a stand-in for the settings that behaves like the runtime settings (a value
 *   is kept in memory first, then saved; a save that is skipped when the value is the same; a clone from `get`),
 *   stand-ins for the parts of the runtime that re-encrypt the credentials, and a record of the order of events
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const assert = require("assert");
const fs = require("fs-extra");
const os = require("os");
const path = require("path");
const child_process = require("child_process");
const sinon = require("sinon");

const NR_TEST_UTILS = require("./index");

const PROJECT = "p1";
const OLD = {
    description: "old description\n",
    summary: "old summary",
    version: "0.0.1",
    dependencies: { "old-dep": "1.0.0" }
};

function clone(value) {
    return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

function sameValue(a, b) {
    try {
        assert.deepStrictEqual(a, b);
        return true;
    } catch (err) {
        return false;
    }
}

// The modules that hold the state of the project storage: the directory of the storage of the projects and the project API
function isolatedModuleKeys() {
    const root = path.dirname(NR_TEST_UTILS.resolve("@node-red/runtime/lib/storage/localfilesystem/projects/index.js")) + path.sep;
    const api = NR_TEST_UTILS.resolve("@node-red/runtime/lib/api/projects.js");
    return Object.keys(require.cache).filter(function(key) { return key.indexOf(root) === 0 || key === api; });
}
// Takes the loaded copies of those modules out of the cache (they are loaded again, fresh, by the next require)
function isolateModules() {
    const saved = {};
    isolatedModuleKeys().forEach(function(key) {
        saved[key] = require.cache[key];
        delete require.cache[key];
    });
    return saved;
}
// Drops the copies that were loaded in between and puts the saved ones back
function restoreModules(saved) {
    isolatedModuleKeys().forEach(function(key) { delete require.cache[key]; });
    Object.keys(saved).forEach(function(key) { require.cache[key] = saved[key]; });
}

/**
 * Creates the harness. Resolves with an object:
 *   - `dir`, `projectDir`, `userDir`: the directories (removed by `cleanup()`)
 *   - `settings`: the stand-in for the runtime settings; `settings.saves` is the list of the values saved to storage,
 *     `settings.failSaves(n, makeError)` makes the next `n` saves fail (the value is kept in memory first, as the
 *     runtime does it)
 *   - `runtime`: stand-ins for `runtime.nodes` and `runtime.storage` (the re-encryption of the credentials)
 *   - `projects`: the real storage of the projects (`updateProject`, `getProject`, `getActiveProject` ...)
 *   - `projectApi`: the real project API of the runtime (`@node-red/runtime/lib/api/projects`)
 *   - `Project`, `gitTools`, `events`: the real modules
 *   - `order`: the events in the order they happened: "saveSettings", "setCredentialSecret", "exportCredentials",
 *     "saveCredentials", "clearCredentials", "stopFlows", "loadFlows", "read:<file>" (a read of README.md or package.json)
 *   - `snapshot()`: what "nothing changed" compares
 *   - `active()`: the active project (the object the storage keeps)
 *   - `cleanup()`
 * Options: `credentialSecret` (the key of the project, default "old"), `mode` ("manual" or "auto"), `files` (extra files
 * to write, name -> content), `withoutPackage` (no package.json), `remotes` (name -> url of the remotes to add)
 */
async function createHarness(options) {
    options = options || {};
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nr-project-update-"));
    const userDir = path.join(dir, "user");
    const projectDir = path.join(userDir, "projects", PROJECT);
    fs.ensureDirSync(projectDir);

    const git = function() {
        child_process.execFileSync("git", Array.prototype.slice.call(arguments), { cwd: projectDir, stdio: "pipe" });
    };
    git("init");
    fs.writeFileSync(path.join(projectDir, "README.md"), OLD.description);
    if (!options.withoutPackage) {
        fs.writeFileSync(path.join(projectDir, "package.json"), JSON.stringify({
            name: PROJECT,
            description: OLD.summary,
            version: OLD.version,
            dependencies: OLD.dependencies,
            "node-red": { settings: { flowFile: "flows.json", credentialsFile: "flows_cred.json" } }
        }, null, 4));
    }
    fs.writeFileSync(path.join(projectDir, ".gitignore"), "*.backup");
    fs.writeFileSync(path.join(projectDir, "flows.json"), "[]");
    fs.writeFileSync(path.join(projectDir, "flows_cred.json"), "{}");
    Object.keys(options.files || {}).forEach(function(name) {
        fs.writeFileSync(path.join(projectDir, name), options.files[name]);
    });
    Object.keys(options.remotes || {}).forEach(function(name) {
        git("remote", "add", name, options.remotes[name]);
    });

    // The storage of the projects keeps its state in the module (the active project, the settings, the secrets of the
    // remotes): the harness works on copies of the modules of the project storage that it loads itself, and
    // `cleanup()` puts the modules of the other tests back, so that nothing of it is left in the process
    const savedModules = isolateModules();

    const order = [];
    const store = {
        projects: {
            projects: {},
            activeProject: PROJECT
        }
    };
    store.projects.projects[PROJECT] = {};
    if (options.credentialSecret !== null) {
        store.projects.projects[PROJECT].credentialSecret = options.credentialSecret === undefined ? "old" : options.credentialSecret;
    }

    // The stand-in for the settings of the runtime: a value is stored in memory first, then saved; a save is skipped
    // when the value equals the one in memory; `get` gives a copy
    const settings = {
        userDir: userDir,
        readOnly: true,
        flowFile: "flows.json",
        editorTheme: { projects: { enabled: true, workflow: { mode: options.mode || "manual" } } },
        saves: [],
        failures: 0,
        makeFailure: null,
        get: function(key) { return clone(store[key]); },
        getUserSettings: function() { return {}; },
        set: function(key, value) {
            const same = sameValue(store[key], value);
            store[key] = clone(value);
            if (same) {
                return Promise.resolve();
            }
            order.push("saveSettings");
            settings.saves.push(clone(value));
            const hold = settings.hold;
            settings.hold = null;
            const outcome = function() {
                if (settings.failures > 0) {
                    settings.failures--;
                    return Promise.reject(settings.makeFailure ? settings.makeFailure() : defaultSaveFailure());
                }
                return Promise.resolve();
            };
            return hold ? hold.then(outcome) : outcome();
        },
        failSaves: function(count, makeError) {
            settings.failures = count;
            settings.makeFailure = makeError || null;
        },
        // The next save waits until `release()` is called (the value is in memory already); resolves with `release`
        holdNextSave: function() {
            let release;
            settings.hold = new Promise(function(resolve) { release = resolve; });
            return release;
        },
        store: store
    };
    function defaultSaveFailure() {
        const err = new Error("ENOSPC: no space left on device, write '" + path.join(userDir, ".config.projects.json") + "'");
        err.code = "ENOSPC";
        return err;
    }

    const runtime = {
        nodes: {
            stopFlows: sinon.spy(async function() { order.push("stopFlows"); }),
            clearContext: sinon.spy(async function() {}),
            loadFlows: sinon.spy(async function() { order.push("loadFlows"); }),
            setCredentialSecret: sinon.spy(function() { order.push("setCredentialSecret"); }),
            clearCredentials: sinon.spy(function() { order.push("clearCredentials"); }),
            exportCredentials: sinon.spy(async function() { order.push("exportCredentials"); return {}; })
        },
        storage: {
            saveCredentials: sinon.spy(async function() { order.push("saveCredentials"); })
        },
        log: { audit: function() {}, warn: function() {}, info: function() {}, error: function() {}, debug: function() {}, trace: function() {}, _: function(k) { return k; } }
    };

    const gitTools = NR_TEST_UTILS.require("@node-red/runtime/lib/storage/localfilesystem/projects/git");
    const sshTools = NR_TEST_UTILS.require("@node-red/runtime/lib/storage/localfilesystem/projects/ssh");
    const Project = NR_TEST_UTILS.require("@node-red/runtime/lib/storage/localfilesystem/projects/Project");
    const projects = NR_TEST_UTILS.require("@node-red/runtime/lib/storage/localfilesystem/projects");
    const projectApi = NR_TEST_UTILS.require("@node-red/runtime/lib/api/projects");
    const authCache = NR_TEST_UTILS.require("@node-red/runtime/lib/storage/localfilesystem/projects/git/authCache");

    // The git of the machine is not asked for its version, and no key of the user is looked for
    sinon.stub(gitTools, "init").resolves({ version: "2.40.0" });
    sinon.stub(sshTools, "init").resolves();

    // A record of the reads of the files that a load of the project reads (for the order of the restore and the load)
    const originalReadFile = fs.readFile;
    const failingReads = {};
    sinon.stub(fs, "readFile").callsFake(function(file) {
        const base = path.basename(String(file));
        if (base === "README.md" || base === "package.json") {
            order.push("read:" + base);
        }
        if (failingReads[base]) {
            const err = failingReads[base];
            delete failingReads[base];
            const failure = Promise.reject(err);
            return failure;
        }
        return originalReadFile.apply(fs, arguments);
    });

    await projects.init(settings, runtime);
    projectApi.init({ storage: { projects: projects }, log: runtime.log, settings: settings });
    await projects.setActiveProject(null, PROJECT);
    order.length = 0;
    runtime.nodes.stopFlows.resetHistory();
    runtime.nodes.loadFlows.resetHistory();
    runtime.storage.saveCredentials.resetHistory();
    settings.saves.length = 0;

    const harness = {
        dir: dir,
        userDir: userDir,
        projectDir: projectDir,
        name: PROJECT,
        OLD: OLD,
        settings: settings,
        runtime: runtime,
        projects: projects,
        projectApi: projectApi,
        Project: Project,
        gitTools: gitTools,
        authCache: authCache,
        order: order,
        active: function() { return projects.getActiveProject(null); },
        // The project has a key that is not valid (the credentials could not be decrypted with it)
        markKeyInvalid: function() { harness.active().credentialSecretInvalid = true; },
        git: git,
        // The next read of this file (README.md or package.json) fails once
        failNextRead: function(base) {
            const err = new Error("EACCES: permission denied, open '" + path.join(projectDir, base) + "'");
            err.code = "EACCES";
            failingReads[base] = err;
        },
        // What a request that fails a check must leave as it was
        snapshot: function() {
            const project = harness.active();
            return {
                readme: fs.existsSync(path.join(projectDir, "README.md")) ? fs.readFileSync(path.join(projectDir, "README.md"), "utf8") : null,
                packageJson: fs.existsSync(path.join(projectDir, "package.json")) ? fs.readFileSync(path.join(projectDir, "package.json"), "utf8") : null,
                gitConfig: fs.readFileSync(path.join(projectDir, ".git", "config"), "utf8"),
                settings: clone(store.projects),
                saves: settings.saves.length,
                credentialSecret: project.credentialSecret,
                credentialSecretInvalid: project.credentialSecretInvalid,
                paths: clone(project.paths),
                gitUser: clone(project.git && project.git.user)
            };
        },
        cleanup: async function() {
            sinon.restore();
            restoreModules(savedModules);
            await fs.remove(dir);
        }
    };
    return harness;
}

// The requests of PUT /projects/:id that fail a check (C1-C9 of the spec of #63) and must change nothing. `body()`
// gives a fresh body; `field` is what the message of the 400 names; `hidden` are texts of the request that must not be
// in the message (the message names only the field, I-8).
const invalidRequests = [];
function invalid(ac, name, body, field, hidden) {
    invalidRequests.push({ ac: ac, name: name, body: body, field: field, hidden: hidden || [] });
}
// B7-AC-1: the types of description, summary, version
[["a number", () => 5, "5"], ["an object", () => ({ k: "secret-object-value" }), "secret-object-value"], ["an array", () => ["secret-array-value"], "secret-array-value"],
 ["null", () => null], ["true", () => true]].forEach(function(entry) {
    invalid("B7-AC-1", "description is " + entry[0], () => ({ description: entry[1]() }), "description", entry[2] ? [entry[2]] : []);
});
invalid("B7-AC-1", "summary is a number", () => ({ summary: 1 }), "summary");
invalid("B7-AC-1", "summary is null", () => ({ summary: null }), "summary");
invalid("B7-AC-1", "version is null", () => ({ version: null }), "version");
invalid("B7-AC-1", "version is an object", () => ({ version: { v: "secret-version-value" } }), "version", ["secret-version-value"]);
// B7-AC-2: dependencies and the key
invalid("B7-AC-2", "dependencies is an array", () => ({ dependencies: [] }), "dependencies");
invalid("B7-AC-2", "dependencies is null", () => ({ dependencies: null }), "dependencies");
invalid("B7-AC-2", "dependencies is a text", () => ({ dependencies: "secret-text-value" }), "dependencies", ["secret-text-value"]);
invalid("B7-AC-2", "dependencies has a value that is not a text", () => ({ dependencies: { a: 1 } }), "dependencies");
invalid("B7-AC-2", "credentialSecret is a number", () => ({ credentialSecret: 123 }), "credentialSecret");
invalid("B7-AC-2", "credentialSecret is an object", () => ({ credentialSecret: { k: "secret-key-object" } }), "credentialSecret", ["secret-key-object"]);
invalid("B7-AC-2", "credentialSecret is true", () => ({ credentialSecret: true }), "credentialSecret");
invalid("B7-AC-2", "credentialSecret is an array", () => ({ credentialSecret: ["secret-key-array"] }), "credentialSecret", ["secret-key-array"]);
invalid("B7-AC-2", "resetCredentialSecret is a text", () => ({ credentialSecret: "n", resetCredentialSecret: "yes" }), "resetCredentialSecret");
invalid("B7-AC-2", "resetCredentialSecret is a number", () => ({ credentialSecret: "n", resetCredentialSecret: 1 }), "resetCredentialSecret");
invalid("B7-AC-2", "currentCredentialSecret is a number", () => ({ credentialSecret: "n", currentCredentialSecret: 5 }), "currentCredentialSecret");
invalid("B7-AC-2", "currentCredentialSecret is an object", () => ({ credentialSecret: "n", currentCredentialSecret: {} }), "currentCredentialSecret");
// B7-AC-3: files
invalid("B7-AC-3", "files is a text", () => ({ files: "secret-files-text" }), "files", ["secret-files-text"]);
invalid("B7-AC-3", "files is null", () => ({ files: null }), "files");
invalid("B7-AC-3", "files is an array", () => ({ files: [] }), "files");
invalid("B7-AC-3", "files.flow is a number", () => ({ files: { flow: 1 } }), "files.flow");
invalid("B7-AC-3", "files.credentials is an object", () => ({ files: { credentials: {} } }), "files.credentials");
invalid("B7-AC-3", "files.package is a number", () => ({ files: { package: 5 } }), "files.package");
invalid("B7-AC-3", "files.package does not end with package.json", () => ({ files: { package: "a/other-secret-name.json" } }), "files.package", ["other-secret-name"]);
// B7-AC-4: git
invalid("B7-AC-4", "git is a number", () => ({ git: 1 }), "git");
invalid("B7-AC-4", "git.user is a text", () => ({ git: { user: "secret-user-text" } }), "git.user", ["secret-user-text"]);
invalid("B7-AC-4", "git.user.name is a number", () => ({ git: { user: { name: 1 } } }), "git.user");
invalid("B7-AC-4", "git.user.email is an object", () => ({ git: { user: { name: "n", email: {} } } }), "git.user");
invalid("B7-AC-4", "git.remotes is an array", () => ({ git: { remotes: [] } }), "git.remotes");
invalid("B7-AC-4", "a remote is a text", () => ({ git: { remotes: { o: "secret-remote-text" } } }), "git.remotes", ["secret-remote-text"]);
invalid("B7-AC-4", "a remote url is a number", () => ({ git: { remotes: { o: { url: 5 } } } }), "git.remotes");
invalid("B7-AC-4", "a remote username is an object", () => ({ git: { remotes: { o: { url: "https://h.example/r.git", username: {} } } } }), "git.remotes");
invalid("B7-AC-4", "a remote password is a number", () => ({ git: { remotes: { o: { url: "https://h.example/r.git", username: "u", password: 7 } } } }), "git.remotes");
invalid("B7-AC-4", "credentials for a remote that does not exist and no url", () => ({ git: { remotes: { nosuch: { username: "u", password: "secret-password-value" } } } }), "git.remotes", ["secret-password-value"]);
// B7-AC-9: the paths are checked before the key changes; the message names the field, not the path
[
    ["files.flow", { flow: "../x" }, "../x"],
    ["files.package", { package: "../p/package.json" }, "../p"],
    ["files.credentials", { credentials: "../c.json" }, "../c.json"]
].forEach(function(entry) {
    invalid("B7-AC-9", entry[0] + " outside the project together with a change of the key",
        () => ({ credentialSecret: "new", currentCredentialSecret: "old", files: JSON.parse(JSON.stringify(entry[1])) }), entry[0], [entry[2]]);
});

module.exports = {
    createHarness: createHarness,
    invalidRequests: invalidRequests,
    PROJECT: PROJECT,
    OLD: OLD
};
